let __v_3845 = pyrt::literals::decode("{\"$dict\":[[\"world-war-one\",{\"$dict\":[[\"names\",{\"$tuple\":[\"world war one\",\"world war 1\",\"ww1\",\"wwi\",\"first world war\",\"great war\"]}],[\"off\",{\"$tuple\":[\"cause\",\"caused\",\"causes\",\"start\",\"started\",\"begin\",\"began\",\"trigger\",\"end\",\"ended\",\"over\",\"finish\",\"finished\",\"why\",\"won\",\"win\",\"winner\",\"beat\",\"victor\",\"victory\",\"prime minister\",\"leader\",\"president\",\"king\",\"emperor\"]}],[\"tell\",\"World War One ran from 1914 to 1918. It began when Archduke Franz Ferdinand was assassinated and the alliances pulled the great powers in, and it ended with Germany's armistice on 11 November 1918.\"],[\"long\",\"World War One lasted four years and three months, from 28 July 1914 to the armistice on 11 November 1918.\"],[\"dead\",\"About 17 million people died in World War One, roughly 9 to 10 million of them soldiers, and about 20 million more were wounded.\"]]}],[\"world-war-two\",{\"$dict\":[[\"names\",{\"$tuple\":[\"world war two\",\"world war 2\",\"ww2\",\"wwii\",\"second world war\"]}],[\"off\",{\"$tuple\":[\"cause\",\"caused\",\"causes\",\"start\",\"started\",\"begin\",\"began\",\"trigger\",\"end\",\"ended\",\"over\",\"finish\",\"finished\",\"why\",\"won\",\"win\",\"winner\",\"beat\",\"victor\",\"victory\",\"died\",\"die\",\"dead\",\"deaths\",\"death\",\"how many\",\"casualties\",\"killed\",\"prime minister\",\"leader\",\"president\",\"king\",\"emperor\"]}],[\"tell\",\"World War Two ran from 1939 to 1945. Britain and France declared war on Germany after it invaded Poland, and it ended with Germany's surrender on 8 May 1945 and Japan's on 2 September.\"],[\"long\",\"World War Two lasted six years and a day, from 1 September 1939 to 2 September 1945.\"]]}],[\"pepys\",{\"$dict\":[[\"names\",{\"$tuple\":[\"samuel pepys\",\"pepys\"]}],[\"tell\",\"Samuel Pepys (1633-1703) was a London naval administrator whose diary, kept from 1660 to 1669 in shorthand, is the best eyewitness account we have of the plague, the Great Fire and the Restoration court. He gave it up because he thought he was going blind, and it was not read until the 1820s.\"]]}],[\"brunel\",{\"$dict\":[[\"names\",{\"$tuple\":[\"isambard kingdom brunel\",\"brunel\"]}],[\"tell\",\"Isambard Kingdom Brunel (1806-1859) was the Victorian engineer of the Great Western Railway, the Clifton Suspension Bridge, the SS Great Britain and the Great Eastern, and the tunnels and viaducts between them. He worked at a scale nobody had tried before, in a top hat, and died at 53 after a stroke, worn out by the Great Eastern.\"],[\"built\",\"Brunel built the Great Western Railway from London to Bristol, the Clifton Suspension Bridge over the Avon, the SS Great Britain (the first iron ship to cross the Atlantic under screw propeller), the Great Eastern, and the Box Tunnel and the viaducts and bridges along the GWR route. His last was the Royal Albert Bridge at Saltash, finished in the year he died.\"],[\"dead\",\"Brunel died on 15 September 1859, aged 53, of a stroke, ten days after the first, unsuccessful launch of the Great Eastern. He had been ill for most of that year and the ship's failures were blamed for it. He is buried at Kensal Green; the Royal Albert Bridge at Saltash, finished in the year he died, is his last work.\"]]}],[\"celts\",{\"$dict\":[[\"names\",{\"$tuple\":[\"celts\",\"celtic people\",\"celtic britain\",\"ancient celts\"]}],[\"off\",{\"$tuple\":[\"celtic fc\",\"celtic park\",\"football\",\"team\",\"match\",\"rangers\",\"language\",\"course\",\"class\",\"music\",\"song\"]}],[\"tell\",\"The Celts were the iron-working peoples of central Europe who spread west to Britain, Ireland, France and Spain from about 500 BC. They wrote nothing down themselves, so what is known comes from Roman writers and from their hillforts, torcs and burials - and from the Celtic languages still spoken in Wales, Scotland, Ireland and Cornwall.\"],[\"built\",\"The Celts built hillforts on high ground, with banks and ditches of earth and timber - Maiden Castle in Dorset is the largest in Britain - and lived in roundhouses of timber, wattle and thatch. They worked iron for swords, tools and ploughs, and fired pots without a wheel.\"]]}],[\"ancient-egyptians\",{\"$dict\":[[\"names\",{\"$tuple\":[\"egyptians\",\"ancient egyptians\",\"egyptian people\"]}],[\"off\",{\"$tuple\":[\"pyramid\",\"pyramids\",\"mummy\",\"mummies\",\"mummify\",\"mummification\",\"pharaoh\",\"hieroglyph\",\"hieroglyphs\",\"cleopatra\",\"tutankhamun\"]}],[\"tell\",\"Ancient Egypt gave us the 365-day calendar, papyrus paper, hieroglyphic writing, glass and the water clock, and Egyptian surgeons were stitching wounds, setting broken bones and removing cataracts by about 2500 BC. Their maths was practical: fractions, a base of ten, and the 3-4-5 triangle for squaring a corner.\"]]}],[\"domesday-book\",{\"$dict\":[[\"names\",{\"$tuple\":[\"domesday book\",\"domesday\",\"doomsday book\",\"doomsday\"]}],[\"off\",{\"$tuple\":[\"doomsday clock\",\"prepper\",\"preppers\",\"film\",\"movie\",\"game\",\"song\",\"album\"]}],[\"tell\",\"The Domesday Book is the survey William the Conqueror ordered at Christmas 1085 and finished the next year: who held every manor, field, mill, wood and pig in England, and what each was worth before and after the Norman conquest. It was called Domesday because, like the Last Judgement, there was no appeal from it.\"]]}],[\"norman-conquest\",{\"$dict\":[[\"names\",{\"$tuple\":[\"normans invade\",\"norman invasion\",\"norman conquest\",\"normans came\"]}],[\"tell\",\"The Normans invaded England in 1066: William of Normandy landed in September, killed King Harold at Hastings on 14 October, and was crowned on Christmas Day. Within twenty years his barons had built the castles and taken the land in the Domesday survey.\"]]}],[\"edward-the-confessor\",{\"$dict\":[[\"names\",{\"$tuple\":[\"edward the confessor\"]}],[\"tell\",\"Edward the Confessor was king of England from 1042 to 1066, the last of the old West Saxon line: he rebuilt Westminster Abbey, where he is buried, and died childless in January 1066, which is why three men fought over the crown that year.\"]]}],[\"nelson\",{\"$dict\":[[\"names\",{\"$tuple\":[\"admiral nelson\",\"horatio nelson\",\"lord nelson\",\"nelson\"]}],[\"off\",{\"$tuple\":[\"mandela\",\"nelson mandela\",\"rugby\",\"new zealand\",\"city of nelson\"]}],[\"tell\",\"Horatio Nelson (1758-1805) was the British admiral who beat the French fleet at the Nile in 1798 and the combined French and Spanish fleet at Trafalgar in 1805, where he was shot and died on his own ship. He lost an arm and an eye in earlier actions and is remembered for the signal 'England expects that every man will do his duty'.\"],[\"dead\",\"Nelson was shot by a French marksman on the quarterdeck of HMS Victory at Trafalgar on 21 October 1805, and died below decks about three hours later, with the battle already won. His body was put in a barrel of brandy for the sail home.\"]]}],[\"richard-the-lionheart\",{\"$dict\":[[\"names\",{\"$tuple\":[\"richard the lionheart\",\"lionheart\",\"richard the first\",\"richard i\"]}],[\"tell\",\"Richard I (1157-1199) was king of England for ten years and spent only about six months of them in England: he went on the Third Crusade, was captured on the way home and ransomed for a fortune, then died besieging a small castle in France.\"]]}],[\"saladin\",{\"$dict\":[[\"names\",{\"$tuple\":[\"saladin\"]}],[\"tell\",\"Saladin (about 1137-1193) was the Kurdish sultan who united Egypt and Syria and took Jerusalem back from the crusaders at Hattin in 1187. He fought Richard the Lionheart to a standstill in the Third Crusade and let the people of Jerusalem go rather than massacre them, which is why he is remembered well on both sides.\"]]}],[\"suleiman\",{\"$dict\":[[\"names\",{\"$tuple\":[\"suleiman the magnificent\",\"suleiman\"]}],[\"tell\",\"Suleiman the Magnificent (1494-1566) ruled the Ottoman Empire for 46 years, took Belgrade and Rhodes, besieged Vienna in 1529, and gave the empire the law code that had him called Suleiman the Lawgiver at home. It was the height of Ottoman power.\"]]}],[\"britain-left-india\",{\"$dict\":[[\"names\",{\"$tuple\":[\"britain leave india\",\"britain left india\",\"british leave india\",\"british raj end\",\"british leave\"]}],[\"tell\",\"Britain left India on 15 August 1947, when the country became independent and was partitioned into India and Pakistan at the same moment, which set off the largest migration and one of the worst episodes of violence of the century.\"]]}],[\"chamberlain\",{\"$dict\":[[\"names\",{\"$tuple\":[\"neville chamberlain\",\"chamberlain\"]}],[\"off\",{\"$tuple\":[\"job\",\"wages\",\"hiring\"]}],[\"tell\",\"Neville Chamberlain (1869-1940) was British prime minister from 1937 to 1940. He flew to Germany three times in 1938 and came back promising 'peace for our time' from Munich, gave up the Sudetenland, and was forced out after the Norway campaign in 1940.\"]]}],[\"boer-war\",{\"$dict\":[[\"names\",{\"$tuple\":[\"boer war\",\"boers\"]}],[\"off\",{\"$tuple\":[\"memorial\",\"monument\",\"statue\",\"museum\"]}],[\"tell\",\"The Boer War ran from 1899 to 1902: the British fought the Dutch-speaking Boer republics of the Transvaal and the Orange Free State over gold and empire. It took a quarter of a million soldiers to win, and the camps where Boer families were held killed about 26,000 people, mostly children.\"]]}],[\"franz-ferdinand\",{\"$dict\":[[\"names\",{\"$tuple\":[\"franz ferdinand\",\"archduke ferdinand\"]}],[\"off\",{\"$tuple\":[\"band\",\"song\",\"guitar\",\"the band\"]}],[\"tell\",\"Archduke Franz Ferdinand of Austria-Hungary was shot in Sarajevo on 28 June 1914 by Gavrilo Princip, a Bosnian Serb nationalist. Austria-Hungary blamed Serbia, the alliances pulled every great power in, and the First World War began five weeks later.\"]]}],[\"russian-revolution\",{\"$dict\":[[\"names\",{\"$tuple\":[\"russian revolution\",\"bolshevik revolution\",\"october revolution\"]}],[\"tell\",\"The Russian Revolution ran through 1917: in February strikes and mutinies pushed the tsar to abdicate, and in October the Bolsheviks under Lenin took over in Petrograd. A civil war followed, the USSR was formed in 1922, and the last tsar was shot with his family in 1918.\"]]}],[\"rasputin\",{\"$dict\":[[\"names\",{\"$tuple\":[\"rasputin\"]}],[\"off\",{\"$tuple\":[\"song\",\"boney m\",\"film\"]}],[\"tell\",\"Grigori Rasputin (1869-1916) was a Siberian peasant who became the tsarina's closest adviser because he seemed able to stop the haemophilia bleeding of the heir, Alexei. By 1916 his influence at court had become a scandal, and a group of nobles poisoned him, shot him and threw him in the Neva.\"]]}],[\"attila\",{\"$dict\":[[\"names\",{\"$tuple\":[\"attila the hun\",\"attila\"]}],[\"tell\",\"Attila (about 406-453) was king of the Huns, the horsemen from the steppe who extracted tribute from the Roman Empire rather than taking it. He raided across the Balkans and into Gaul, was beaten at Chalons in 451, and died in 453 - after which his empire fell apart within a generation.\"]]}],[\"pearl-harbour\",{\"$dict\":[[\"names\",{\"$tuple\":[\"pearl harbour\",\"pearl harbor\"]}],[\"off\",{\"$tuple\":[\"film\",\"movie\"]}],[\"tell\",\"Japan attacked the US fleet at Pearl Harbor in Hawaii on 7 December 1941, sinking or damaging most of the battleships in a morning and killing about 2,400 people. The United States declared war the next day, which is how it entered the Second World War.\"]]}],[\"bismarck\",{\"$dict\":[[\"names\",{\"$tuple\":[\"otto von bismarck\",\"bismarck\"]}],[\"off\",{\"$tuple\":[\"battleship\",\"ship\",\"herring\"]}],[\"tell\",\"Otto von Bismarck (1815-1898) was the Prussian statesman who united Germany in 1871 by three short wars and then ran it as chancellor until 1890. He called his method Realpolitik - what works rather than what is right - and built the welfare state and alliances that kept the peace in Europe for twenty years after he left.\"]]}],[\"ireland-republic\",{\"$dict\":[[\"names\",{\"$tuple\":[\"ireland become a republic\",\"ireland became a republic\",\"ireland a republic\",\"republic of ireland\",\"irish republic\"]}],[\"off\",{\"$tuple\":[\"northern ireland\",\"holiday\",\"visit\",\"trip\",\"passport\",\"move to\"]}],[\"tell\",\"Ireland became a republic on 18 April 1949, when the Republic of Ireland Act came into force and the country cut its last constitutional link with the Crown. It had been the Irish Free State since 1922, after the war of independence and the treaty.\"]]}],[\"depression-1929\",{\"$dict\":[[\"names\",{\"$tuple\":[\"the depression start\",\"the depression begin\",\"the depression happen\",\"the depression end\",\"the depression finish\"]}],[\"tell\",\"The Great Depression began with the Wall Street crash in October 1929 and lasted through the 1930s: banks failed, a quarter of American workers lost their jobs, and world trade shrank by two thirds. It ended only with the rearmament that came with the Second World War.\"]]}],[\"augustus\",{\"$dict\":[[\"names\",{\"$tuple\":[\"caesar augustus\",\"augustus\",\"octavian\",\"octavius\",\"first roman emperor\"]}],[\"tell\",\"Augustus (63 BC-14 AD) was the first Roman emperor: Julius Caesar's adopted heir, who took the name Augustus when he came out on top of the civil wars in 27 BC and ruled for forty years. He kept the forms of the republic while holding the power of a king, and his reign opened the two centuries of peace Romans called the Pax Romana.\"]]}],[\"votes-for-women\",{\"$dict\":[[\"names\",{\"$tuple\":[\"women get the vote\",\"women got the vote\",\"women vote\",\"suffragettes\",\"suffrage\",\"votes for women\",\"woman get the vote\",\"women the vote\"]}],[\"off\",{\"$tuple\":[\"america\",\"american\",\"usa\",\"in the us\",\"in the usa\",\"united states\",\"black\",\"african\",\"australia\",\"aus\",\"new zealand\",\"nz\",\"canada\",\"france\",\"germany\",\"india\",\"ireland\",\"switzerland\",\"south africa\",\"18\",\"16\",\"17\",\"21 year\",\"year olds\",\"year old\",\"age\",\"aged\",\"old\",\"young people\",\"younger\",\"teenagers\",\"teenager\"]}],[\"tell\",\"Women got the vote in Britain in two steps. In 1918 women over 30 who met a property test, and all men over 21, were given the vote; in 1928 women got it at 21, on the same terms as men. The suffragettes' campaign before the war, and women's work in the war, both pushed it through.\"]]}],[\"slavery-end\",{\"$dict\":[[\"names\",{\"$tuple\":[\"slave trade\",\"slavery\",\"slaves\"]}],[\"off\",{\"$tuple\":[\"britain\",\"british\",\"uk\",\"england\",\"english\",\"empire\",\"transatlantic\",\"america\",\"american\",\"usa\",\"us\",\"united states\",\"france\",\"french\",\"spain\",\"spanish\",\"portugal\",\"brazil\",\"india\",\"canada\",\"australia\",\"1865\",\"1807\",\"1833\",\"civil war\",\"bible\",\"god\",\"jesus\",\"church\",\"quran\",\"islam\",\"sin\",\"moral\",\"reparations\",\"museum\"]}],[\"tell\",\"It depends where: Britain banned the trade in 1807 and slavery in its colonies in 1833, France abolished it in 1848, the United States in 1865 with the 13th Amendment, and Brazil was last in 1888.\"]]}],[\"slavery-in-america\",{\"$dict\":[[\"names\",{\"$tuple\":[\"slavery in america\",\"american slavery\",\"slavery in the us\",\"slavery in the united states\",\"america abolish slavery\",\"america abolished slavery\",\"us abolish slavery\",\"us abolished slavery\",\"thirteenth amendment\",\"13th amendment\"]}],[\"tell\",\"The United States abolished slavery with the 13th Amendment, ratified in December 1865, after the Civil War. The Emancipation Proclamation of 1863 had freed slaves only in the rebel states, so the amendment was what ended it everywhere.\"]]}],[\"rosa-parks\",{\"$dict\":[[\"names\",{\"$tuple\":[\"rosa parks\"]}],[\"tell\",\"Rosa Parks was the black seamstress in Montgomery, Alabama, who on 1 December 1955 refused to give up her bus seat to a white passenger. Her arrest set off the 381-day bus boycott led by a young Martin Luther King, and the Supreme Court struck down bus segregation the next year.\"]]}],[\"charles-dickens\",{\"$dict\":[[\"names\",{\"$tuple\":[\"charles dickens\",\"dickens\"]}],[\"tell\",\"Charles Dickens (1812-1870) was the Victorian novelist who wrote Oliver Twist, A Christmas Carol, David Copperfield and Bleak House. He worked in a boot-polish factory as a boy, and that memory of child labour runs through his books, which were published in monthly parts and read aloud across the country.\"]]}],[\"stalin\",{\"$dict\":[[\"names\",{\"$tuple\":[\"stalin\",\"joseph stalin\",\"josef stalin\"]}],[\"off\",{\"$tuple\":[\"star trek\",\"or is it\"]}],[\"tell\",\"Joseph Stalin (1878-1953) ruled the Soviet Union from the late 1920s until he died. He forced through collectivisation of farming and crash industrialisation, at the cost of famines that killed millions, then led the country through the Second World War after Hitler invaded in 1941.\"]]}],[\"lenin\",{\"$dict\":[[\"names\",{\"$tuple\":[\"lenin\",\"vladimir lenin\"]}],[\"tell\",\"Vladimir Lenin (1870-1924) was the revolutionary who led the Bolsheviks to power in Russia in October 1917, pulled the country out of the First World War, and founded the Soviet state. He died in 1924 after a series of strokes, and Stalin took over the party machine.\"]]}],[\"world-wars-difference\",{\"$dict\":[[\"names\",{\"$tuple\":[\"difference between ww1 and ww2\",\"difference between the world wars\",\"difference between world war one and world war two\",\"how were the world wars different\",\"ww1 and ww2 difference\"]}],[\"tell\",\"World War One was mostly trench fighting in France and Belgium, and it ended with Germany intact and a peace the next war was blamed on. World War Two was a war of movement, bombing and genocide across Europe, Africa and the Pacific, it ended with both aggressors occupied, and it killed about four times as many people.\"]]}],[\"vietnam-war\",{\"$dict\":[[\"names\",{\"$tuple\":[\"vietnam war\",\"war in vietnam\"]}],[\"tell\",\"The Vietnam War ran from 1955 to 1975, when North Vietnam and the Viet Cong beat South Vietnam and its American backers. It killed about 3 million people, more than half of them Vietnamese civilians.\"],[\"long\",\"The Vietnam War ran about 20 years, from 1955 to the fall of Saigon on 30 April 1975; American combat troops were there from 1965 to 1973.\"]]}],[\"colosseum\",{\"$dict\":[[\"names\",{\"$tuple\":[\"colosseum\",\"coliseum\"]}],[\"off\",{\"$tuple\":[\"visit\",\"visiting\",\"worth seeing\",\"ticket\",\"tickets\",\"queue\",\"hotel\",\"crowds\",\"guided\",\"skip the line\",\"best time\",\"worth\",\"enough\",\"days\",\"whole day\",\"how long\",\"take\"]}],[\"tell\",\"The Colosseum was built in Rome between 72 and 80 AD, under the emperors Vespasian and Titus, with loot from the Jewish temple in Jerusalem. It held about 50,000 people for gladiator fights and animal hunts.\"]]}],[\"tower-of-london\",{\"$dict\":[[\"names\",{\"$tuple\":[\"tower of london\"]}],[\"off\",{\"$tuple\":[\"visit\",\"visiting\",\"worth seeing\",\"ticket\",\"tickets\",\"queue\",\"hotel\",\"crowds\",\"guided\",\"skip the line\",\"best time\"]}],[\"tell\",\"The Tower of London was started by William the Conqueror in the 1070s, and later kings ringed it with walls and towers. It has been a fortress, a palace, a prison and a mint, and it holds the Crown Jewels.\"]]}],[\"marshall-plan\",{\"$dict\":[[\"names\",{\"$tuple\":[\"marshall plan\"]}],[\"tell\",\"The Marshall Plan was the American programme that sent about 13 billion dollars to western Europe between 1948 and 1952 to rebuild after the war. It was offered to the Soviet Union and its neighbours as well, and Stalin refused.\"]]}],[\"first-president\",{\"$dict\":[[\"names\",{\"$tuple\":[\"first president of the united states\",\"first president of the usa\",\"first president of america\",\"first us president\",\"first american president\",\"george washington\",\"first president of the us\",\"first president\"]}],[\"off\",{\"$tuple\":[\"france\",\"french\",\"ireland\",\"irish\",\"mexico\",\"brazil\",\"india\",\"china\",\"russia\",\"south africa\",\"turkey\",\"israel\",\"egypt\",\"kenya\",\"nigeria\",\"ghana\",\"pakistan\",\"philippines\",\"korea\",\"singapore\"]}],[\"tell\",\"George Washington was the first president of the United States, from 1789 to 1797. The first electoral college chose him unanimously and he stepped down after two terms, which set the pattern every later president followed.\"]]}],[\"nickname\",{\"$dict\":[[\"names\",{\"$tuple\":[\"last tsar of russia\",\"last tsar\",\"tsar nicholas\",\"nicholas ii\",\"tsar of russia\",\"nicholas the second\"]}],[\"tell\",\"Nicholas II was the last tsar of Russia. He gave up the throne in March 1917 as the war and the bread queues broke his country, and he and his family were shot by the Bolsheviks in Yekaterinburg in July 1918.\"]]}],[\"jfk\",{\"$dict\":[[\"names\",{\"$tuple\":[\"jfk\",\"john f kennedy\",\"john fitzgerald kennedy\",\"president kennedy\",\"kennedy\"]}],[\"tell\",\"John F. Kennedy was the 35th US president, from 1961 until he was shot in Dallas on 22 November 1963. He faced the Soviet Union down over Cuba in 1962 and set the goal of landing a man on the moon before the decade was out.\"]]}],[\"anne-boleyn\",{\"$dict\":[[\"names\",{\"$tuple\":[\"anne boleyn\"]}],[\"tell\",\"Anne Boleyn was Henry VIII's second wife, from 1533 to 1536, and the mother of Elizabeth I. When she gave him no son he had her tried for adultery and executed at the Tower of London in May 1536.\"]]}],[\"qin-shi-huang\",{\"$dict\":[[\"names\",{\"$tuple\":[\"first emperor of china\",\"qin shi huang\",\"qin shihuang\",\"emperor of china\"]}],[\"tell\",\"Qin Shi Huang was the first emperor of a united China, from 221 to 210 BC. He standardised writing, money and weights, joined up the Great Wall, and was buried with the terracotta army.\"]]}]]}")?;
