let __v_3846 = pyrt::literals::decode("{\"$dict\":[[\"aeroplane\",{\"$dict\":[[\"names\",{\"$tuple\":[\"aeroplane\",\"airplane\",\"first flight\",\"first plane\"]}],[\"off\",{\"$tuple\":[\"fly\",\"flying\",\"flight\",\"flights\",\"airport\",\"luggage\",\"bag\",\"book\",\"ticket\",\"seat\",\"carry\",\"delay\",\"cancel\",\"turbulence\",\"scared\",\"afraid\"]}],[\"tell\",\"The Wright brothers, Orville and Wilbur, made the first powered aeroplane flight on 17 December 1903 at Kitty Hawk: 12 seconds and 36 metres. Their edge was working out how to control a wing, not just how to lift one.\"]]}],[\"car\",{\"$dict\":[[\"names\",{\"$tuple\":[\"car\",\"cars\",\"automobile\",\"motor car\"]}],[\"off\",{\"$tuple\":[\"my\",\"your\",\"our\",\"insurance\",\"mot\",\"tax\",\"lease\",\"hire\",\"buy\",\"buying\",\"second hand\",\"secondhand\",\"sell\",\"worth\",\"offer\",\"offering\",\"haggle\",\"haggling\",\"haggle over\",\"pay\",\"paying\",\"price\",\"prices\",\"cost\",\"costs\",\"how much should i pay\",\"deal\",\"dealer\",\"garage\",\"test drive\",\"finance\",\"part exchange\",\"part-exchange\",\"good\",\"best\",\"cheap\",\"cheapest\",\"affordable\",\"reliable\",\"recommend\",\"recommended\",\"advice\",\"new driver\",\"learner\",\"first time driver\",\"bought\",\"better\",\"cheaper\",\"sensible\",\"practical\",\"which\",\"should\"]}],[\"tell\",\"Karl Benz built the first car with a petrol engine in 1885 and patented it in 1886, and his wife Bertha drove it 100 km the next year to prove it worked. Henry Ford's Model T, from 1908, was the one that made cars ordinary.\"]]}],[\"television\",{\"$dict\":[[\"names\",{\"$tuple\":[\"television\",\"tv\"]}],[\"tell\",\"John Logie Baird gave the first public demonstration of television in London in 1926, using a spinning disc. Philo Farnsworth's all-electronic system, shown in 1927, is the one every modern set works on.\"]]}],[\"steam-engine\",{\"$dict\":[[\"names\",{\"$tuple\":[\"steam engine\",\"steam engines\"]}],[\"tell\",\"Thomas Newcomen built the first practical steam engine in 1712, to pump water out of mines, and James Watt improved it from 1769 with a separate condenser that wasted far less heat. Watt's engine is the one that powered the Industrial Revolution.\"]]}],[\"electricity\",{\"$dict\":[[\"names\",{\"$tuple\":[\"electricity\",\"electric power\"]}],[\"tell\",\"Nobody invented electricity: it is a force in nature, and people learned to make and use it over about 150 years. Franklin showed lightning was electric in 1752, Volta made the first battery in 1800, Faraday built the first generator in 1831, and Edison opened the first power station in 1882.\"]]}],[\"internet\",{\"$dict\":[[\"names\",{\"$tuple\":[\"internet\",\"world wide web\",\"the web\"]}],[\"tell\",\"No one person invented the internet: ARPANET linked four American university computers in 1969 and the network grew from there. Tim Berners-Lee invented the world wide web on top of it in 1989, at CERN, so documents could be linked.\"]]}]]}")?;
